  1→//! Failure telemetry: scrubbing, consent, and local report storage.
  2→//!
  3→//! After a successful recovery (step eventually passes after retry, fix,
  4→//! or shell), optionally prompts the user to share a scrubbed failure report.
  5→//! Reports are stored locally as YAML files under `~/.bivvy/failure-reports/`.
  6→
  7→use std::collections::HashMap;
  8→use std::fmt;
  9→use std::path::{Path, PathBuf};
 10→use std::sync::LazyLock;
 11→
 12→use regex::Regex;
 13→use serde::{Deserialize, Serialize};
 14→
 15→use crate::error::Result;
 16→use crate::secrets::mask::OutputMasker;
 17→use crate::secrets::pattern::SecretMatcher;
 18→use crate::ui::{Prompt, PromptOption, PromptType, UserInterface};
 19→
 20→/// Regex for scrubbing filesystem paths.
 21→static PATH_REGEX: LazyLock<Regex> = LazyLock::new(|| {
 22→    Regex::new(r"(?:/Users/[^\s:]+|/home/[^\s:]+|/tmp/[^\s:]+|C:\\Users\\[^\s:]+)")
 23→        .expect("PATH_REGEX must compile")
 24→});
 25→
 26→/// Regex for scrubbing token-like strings (hex > 16 chars, base64 blobs, known prefixes).
 27→static TOKEN_REGEX: LazyLock<Regex> = LazyLock::new(|| {
 28→    Regex::new(r"(?:ghp_[A-Za-z0-9]{36,}|gho_[A-Za-z0-9]{36,}|sk-[A-Za-z0-9]{20,}|xoxb-[A-Za-z0-9\-]+|xoxp-[A-Za-z0-9\-]+|[A-Fa-f0-9]{32,}|[A-Za-z0-9+/]{40,}={0,2})")
 29→        .expect("TOKEN_REGEX must compile")
 30→});
 31→
 32→/// Maximum length of scrubbed error output in a report.
 33→const MAX_ERROR_LENGTH: usize = 500;
 34→
 35→/// User's telemetry consent preference.
 36→#[derive(Debug, Clone, PartialEq, Eq)]
 37→pub enum TelemetryConsent {
 38→    /// Send this one report.
 39→    Send,
 40→    /// Don't send this report.
 41→    NoThanks,
 42→    /// Always send (save preference).
 43→    Always,
 44→    /// Never ask again (save preference).
 45→    Never,
 46→}
 47→
 48→impl fmt::Display for TelemetryConsent {
 49→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 50→        match self {
 51→            TelemetryConsent::Send => write!(f, "send"),
 52→            TelemetryConsent::NoThanks => write!(f, "no_thanks"),
 53→            TelemetryConsent::Always => write!(f, "always"),
 54→            TelemetryConsent::Never => write!(f, "never"),
 55→        }
 56→    }
 57→}
 58→
 59→/// A scrubbed failure report.
 60→#[derive(Debug, Clone, Serialize, Deserialize)]
 61→pub struct FailureReport {
 62→    /// Step name (e.g., "bundler").
 63→    pub step_name: String,
 64→    /// Scrubbed command (e.g., "bundle install").
 65→    pub command_scrubbed: String,
 66→    /// Process exit code.
 67→    pub exit_code: Option<i32>,
 68→    /// Scrubbed error output (first 500 chars).
 69→    pub error_scrubbed: String,
 70→    /// Recovery action taken (e.g., "retry", "shell → retry").
 71→    pub recovery_action: String,
 72→    /// Bivvy version.
 73→    pub bivvy_version: String,
 74→    /// Platform string (e.g., "macos-aarch64").
 75→    pub platform: String,
 76→}
 77→
 78→/// Scrub sensitive data from text for telemetry.
 79→///
 80→/// 1. Masks known secret env var values using `OutputMasker`
 81→/// 2. Replaces filesystem paths with `[PATH]`
 82→/// 3. Replaces token-like strings with `[REDACTED]`
 83→/// 4. Truncates to `MAX_ERROR_LENGTH` chars
 84→pub fn scrub_for_telemetry(input: &str, step_env: &HashMap<String, String>) -> String {
 85→    let matcher = SecretMatcher::with_builtins();
 86→    let mut masker = OutputMasker::new();
 87→
 88→    // Mask known secret env var values
 89→    for (key, value) in step_env {
 90→        if matcher.is_secret(key) && !value.is_empty() {
 91→            masker.add_secret(value);
 92→        }
 93→    }
 94→
 95→    let mut result = masker.mask(input);
 96→
 97→    // Scrub filesystem paths
 98→    result = PATH_REGEX.replace_all(&result, "[PATH]").to_string();
 99→
100→    // Scrub token-like strings

  1→//! Project index management.
  2→//!
  3→//! This module provides the [`ProjectIndex`] for tracking all known
  4→//! projects that Bivvy has been used with.
  5→
  6→use chrono::{DateTime, Utc};
  7→use serde::{Deserialize, Serialize};
  8→use std::collections::HashMap;
  9→use std::fs;
 10→use std::path::PathBuf;
 11→
 12→use super::ProjectId;
 13→
 14→/// Index of all known projects.
 15→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 16→pub struct ProjectIndex {
 17→    pub projects: HashMap<String, ProjectEntry>,
 18→}
 19→
 20→/// Entry for a project in the index.
 21→#[derive(Debug, Clone, Serialize, Deserialize)]
 22→pub struct ProjectEntry {
 23→    pub path: String,
 24→    pub git_remote: Option<String>,
 25→    pub name: String,
 26→    pub last_accessed: DateTime<Utc>,
 27→}
 28→
 29→impl ProjectIndex {
 30→    /// Get the index file path.
 31→    pub fn file_path() -> PathBuf {
 32→        dirs::home_dir()
 33→            .unwrap_or_else(|| PathBuf::from("~"))
 34→            .join(".bivvy")
 35→            .join("projects")
 36→            .join("index.yml")
 37→    }
 38→
 39→    /// Load the project index.
 40→    pub fn load() -> crate::error::Result<Self> {
 41→        let path = Self::file_path();
 42→
 43→        if !path.exists() {
 44→            return Ok(Self::default());
 45→        }
 46→
 47→        let content = fs::read_to_string(&path)?;
 48→        let index: Self = serde_yaml::from_str(&content).map_err(|e| {
 49→            crate::error::BivvyError::ConfigParseError {
 50→                path,
 51→                message: e.to_string(),
 52→            }
 53→        })?;
 54→
 55→        Ok(index)
 56→    }
 57→
 58→    /// Save the project index using atomic write.
 59→    ///
 60→    /// Uses the write-to-temp-then-rename pattern to prevent corruption.
 61→    pub fn save(&self) -> crate::error::Result<()> {
 62→        let path = Self::file_path();
 63→
 64→        if let Some(parent) = path.parent() {
 65→            fs::create_dir_all(parent)?;
 66→        }
 67→
 68→        let content = serde_yaml::to_string(self).map_err(|e| {
 69→            crate::error::BivvyError::ConfigValidationError {
 70→                message: format!("Failed to serialize index: {}", e),
 71→            }
 72→        })?;
 73→
 74→        // Atomic write: write to temp file, then rename
 75→        let temp_path = path.with_extension("yml.tmp");
 76→        fs::write(&temp_path, &content)?;
 77→        fs::rename(&temp_path, &path)?;
 78→
 79→        Ok(())
 80→    }
 81→
 82→    /// Update or add a project to the index.
 83→    pub fn update(&mut self, project_id: &ProjectId) {
 84→        let entry = ProjectEntry {
 85→            path: project_id.path().to_string_lossy().to_string(),
 86→            git_remote: project_id.git_remote().map(String::from),
 87→            name: project_id.name().to_string(),
 88→            last_accessed: Utc::now(),
 89→        };
 90→        self.projects.insert(project_id.hash().to_string(), entry);
 91→    }
 92→
 93→    /// Remove projects that no longer exist on disk.
 94→    pub fn prune(&mut self) -> Vec<String> {
 95→        let mut removed = Vec::new();
 96→
 97→        self.projects.retain(|hash, entry| {
 98→            let exists = std::path::Path::new(&entry.path).exists();
 99→            if !exists {
100→                removed.push(hash.clone());
101→            }
102→            exists
103→        });
104→
105→        removed
106→    }
107→
108→    /// List all projects.
109→    pub fn list(&self) -> impl Iterator<Item = (&str, &ProjectEntry)> {
110→        self.projects.iter().map(|(k, v)| (k.as_str(), v))
111→    }
112→
113→    /// Get a project by hash.
114→    pub fn get(&self, hash: &str) -> Option<&ProjectEntry> {
115→        self.projects.get(hash)
116→    }
117→
118→    /// Number of tracked projects.
119→    pub fn len(&self) -> usize {
120→        self.projects.len()

